// DocumentBuilderFactory + DocumentBuilder wczytuja CALY dokument XML
// do pamieci jako DRZEWO obiektow (Document -> Element -> Node...).
// InputSource + StringReader pozwalaja podac parserowi XML jako
// zwykly String (zamiast pliku/strumienia sieciowego).

DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
DocumentBuilder builder = factory.newDocumentBuilder();
Document document = builder.parse(new InputSource(new StringReader(xml)));
document.getDocumentElement().normalize();
// normalize() "scala" sasiadujace wezly tekstowe w jeden - dobra
// praktyka po sparsowaniu, przed przetwarzaniem drzewa

System.out.println(document.getDocumentElement().getNodeName()); // np. "users"

// getElementsByTagName(nazwa) - zwraca WSZYSTKIE elementy o danej
// nazwie w calym dokumencie (niezaleznie od poziomu zagniezdzenia).

NodeList userNodes = document.getElementsByTagName("user");
for (int i = 0; i < userNodes.getLength(); i++) {
    Node userNode = userNodes.item(i);
    if (userNode.getNodeType() == Node.ELEMENT_NODE) {
        Element userElement = (Element) userNode;
        String id = userElement.getAttribute("id");
        String name = userElement.getElementsByTagName("name").item(0).getTextContent();
        System.out.println("user[id=" + id + "] -> " + name);
    }
}
